//! Field-complete semantic mapping. No native layout or received value is reinterpreted.
use oer_esp32s31_knowledge::calibration_cache as codec;
use oer_esp32s31_phy::{
    PhyCalibrationIdentity, PhyCalibrationSnapshot,
    state::{PhyBluetoothCalibration, PhyCommonCalibration, PhyWifiCalibration},
};

pub fn record(snapshot: PhyCalibrationSnapshot) -> codec::CalibrationRecord {
    codec::CalibrationRecord {
        schema: snapshot.schema,
        identity: codec::CalibrationIdentity {
            rf_cal_version: snapshot.identity.rf_cal_version,
            base_mac_address: snapshot.identity.base_mac_address,
            mac_extension: snapshot.identity.mac_extension,
        },
        common: codec::CommonCalibration {
            temperature: snapshot.common.temperature,
            rfpll_reference_temperature: snapshot.common.rfpll_reference_temperature,
            rxcal_reference_temperature: snapshot.common.rxcal_reference_temperature,
            txcal_reference_temperature: snapshot.common.txcal_reference_temperature,
            power_reference_temperature: snapshot.common.power_reference_temperature,
            sensor_index: snapshot.common.sensor_index,
            crystal_selector: snapshot.common.crystal_selector,
            rc_result: snapshot.common.rc_result,
            filter_dcap: snapshot.common.filter_dcap,
            rc_calibrated: snapshot.common.rc_calibrated,
            dcode: snapshot.common.dcode,
            i2c_frequency_parameter: snapshot.common.i2c_frequency_parameter,
            xtal_duty: snapshot.common.xtal_duty,
            clear_tone_after_ready: snapshot.common.clear_tone_after_ready,
        },
        wifi: codec::WifiCalibration {
            tx_gain_adjustment: snapshot.wifi.tx_gain_adjustment,
            baseband_calibrated: snapshot.wifi.baseband_calibrated,
            pwdet_calibrated: snapshot.wifi.pwdet_calibrated,
            tx_power_calibrated: snapshot.wifi.tx_power_calibrated,
            tx_iq_calibrated: snapshot.wifi.tx_iq_calibrated,
            rx_gain_dc_calibrated: snapshot.wifi.rx_gain_dc_calibrated,
            rx_gain_tables_initialized: snapshot.wifi.rx_gain_tables_initialized,
            rx_saturation_detected: snapshot.wifi.rx_saturation_detected,
            tx_dco: snapshot.wifi.tx_dco,
            tx_reference_codes: snapshot.wifi.tx_reference_codes,
            tx_capacitance: snapshot.wifi.tx_capacitance,
            tx_power_curve: snapshot.wifi.tx_power_curve,
            tx_power_corrections: snapshot.wifi.tx_power_corrections,
            tx_power_adjustment: snapshot.wifi.tx_power_adjustment,
            calibrated_attenuation: snapshot.wifi.calibrated_attenuation,
            tx_iq_config: snapshot.wifi.tx_iq_config,
            tx_iq_coefficient: snapshot.wifi.tx_iq_coefficient,
            rx_iq_coefficients: snapshot.wifi.rx_iq_coefficients,
            external_dcode: snapshot.wifi.external_dcode,
            calibration_temperature: snapshot.wifi.calibration_temperature,
            calibration_channel: snapshot.wifi.calibration_channel,
            wifi_rx_table_last_index: snapshot.wifi.wifi_rx_table_last_index,
            shared_rx_table_last_index: snapshot.wifi.shared_rx_table_last_index,
            wifi_index_dc: snapshot.wifi.wifi_index_dc,
            wifi_fine_dc: snapshot.wifi.wifi_fine_dc,
            shared_index_dc: snapshot.wifi.shared_index_dc,
        },
        bluetooth: codec::BluetoothCalibration {
            tx_dc_calibrated: snapshot.bluetooth.tx_dc_calibrated,
            tx_power_calibrated: snapshot.bluetooth.tx_power_calibrated,
            tx_dco: snapshot.bluetooth.tx_dco,
            tx_power_curve: snapshot.bluetooth.tx_power_curve,
            tx_power_corrections: snapshot.bluetooth.tx_power_corrections,
            tx_power_adjustment: snapshot.bluetooth.tx_power_adjustment,
        },
    }
}

pub fn native(record: codec::CalibrationRecord) -> PhyCalibrationSnapshot {
    PhyCalibrationSnapshot {
        schema: record.schema,
        identity: PhyCalibrationIdentity {
            rf_cal_version: record.identity.rf_cal_version,
            base_mac_address: record.identity.base_mac_address,
            mac_extension: record.identity.mac_extension,
        },
        common: PhyCommonCalibration {
            temperature: record.common.temperature,
            rfpll_reference_temperature: record.common.rfpll_reference_temperature,
            rxcal_reference_temperature: record.common.rxcal_reference_temperature,
            txcal_reference_temperature: record.common.txcal_reference_temperature,
            power_reference_temperature: record.common.power_reference_temperature,
            sensor_index: record.common.sensor_index,
            crystal_selector: record.common.crystal_selector,
            rc_result: record.common.rc_result,
            filter_dcap: record.common.filter_dcap,
            rc_calibrated: record.common.rc_calibrated,
            dcode: record.common.dcode,
            i2c_frequency_parameter: record.common.i2c_frequency_parameter,
            xtal_duty: record.common.xtal_duty,
            clear_tone_after_ready: record.common.clear_tone_after_ready,
        },
        wifi: PhyWifiCalibration {
            tx_gain_adjustment: record.wifi.tx_gain_adjustment,
            baseband_calibrated: record.wifi.baseband_calibrated,
            pwdet_calibrated: record.wifi.pwdet_calibrated,
            tx_power_calibrated: record.wifi.tx_power_calibrated,
            tx_iq_calibrated: record.wifi.tx_iq_calibrated,
            rx_gain_dc_calibrated: record.wifi.rx_gain_dc_calibrated,
            rx_gain_tables_initialized: record.wifi.rx_gain_tables_initialized,
            rx_saturation_detected: record.wifi.rx_saturation_detected,
            tx_dco: record.wifi.tx_dco,
            tx_reference_codes: record.wifi.tx_reference_codes,
            tx_capacitance: record.wifi.tx_capacitance,
            tx_power_curve: record.wifi.tx_power_curve,
            tx_power_corrections: record.wifi.tx_power_corrections,
            tx_power_adjustment: record.wifi.tx_power_adjustment,
            calibrated_attenuation: record.wifi.calibrated_attenuation,
            tx_iq_config: record.wifi.tx_iq_config,
            tx_iq_coefficient: record.wifi.tx_iq_coefficient,
            rx_iq_coefficients: record.wifi.rx_iq_coefficients,
            external_dcode: record.wifi.external_dcode,
            calibration_temperature: record.wifi.calibration_temperature,
            calibration_channel: record.wifi.calibration_channel,
            wifi_rx_table_last_index: record.wifi.wifi_rx_table_last_index,
            shared_rx_table_last_index: record.wifi.shared_rx_table_last_index,
            wifi_index_dc: record.wifi.wifi_index_dc,
            wifi_fine_dc: record.wifi.wifi_fine_dc,
            shared_index_dc: record.wifi.shared_index_dc,
        },
        bluetooth: PhyBluetoothCalibration {
            tx_dc_calibrated: record.bluetooth.tx_dc_calibrated,
            tx_power_calibrated: record.bluetooth.tx_power_calibrated,
            tx_dco: record.bluetooth.tx_dco,
            tx_power_curve: record.bluetooth.tx_power_curve,
            tx_power_corrections: record.bluetooth.tx_power_corrections,
            tx_power_adjustment: record.bluetooth.tx_power_adjustment,
        },
    }
}
